SELECT n.gender, rt.role, cn.name, COUNT(*)
FROM title as t, movie_companies as mc, company_name as cn, company_type as ct, kind_type as kt, cast_info as ci, name as n, role_type as rt, movie_info as mi1, info_type as it1, person_info as pi, info_type as it2, non_leaf_478
WHERE (rt.role IN ('actor','costume designer','editor','guest','miscellaneous crew','producer','writer')) AND mc.movie_id = non_leaf_478.t_id AND (it1.id IN ('4')) AND it2.id = non_leaf_478.pi_info_type_id AND ct.id = mc.company_type_id AND mc.movie_id = non_leaf_478.ci_movie_id AND cn.id = mc.company_id AND (kt.kind IN ('movie','tv mini series','tv movie','tv series','video game','video movie')) AND (pi.info ILIKE '%200%') AND (mi1.info ILIKE '%e%') AND (it2.id IN ('38')) AND it1.id = non_leaf_478.mi1_info_type_id AND (t.production_year >= 1875) AND (t.production_year <= 2015);